<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/reports.php';require_once __DIR__.'/../includes/moderation-stats.php';
function stats_ok($value,$why){if(!$value)throw new RuntimeException($why);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);
$now=new DateTimeImmutable('2026-10-24 12:00:00',new DateTimeZone('America/Buenos_Aires'));$range=moderation_period(['period'=>'today'],$now);stats_ok($range['start']==='2026-10-24 03:00:00'&&$range['end']==='2026-10-25 03:00:00','Argentina UTC boundaries');stats_ok(moderation_period(['period'=>'7'],$now)['from']==='2026-10-18','inclusive seven days');
foreach([['period'=>'bad'],['period'=>'custom','from'=>'2026-02-30','to'=>'2026-03-01'],['period'=>'custom','from'=>'2026-10-25','to'=>'2026-10-25'],['period'=>'custom','from'=>'2026-10-24','to'=>'2026-10-23']] as $bad){try{moderation_period($bad,$now);throw new RuntimeException('Accepted bad period');}catch(CatalogException $e){stats_ok($e->status===422,'validation status');}}
audit_q($db,"INSERT INTO users(name,public_name,email,password_hash,role,created_at) VALUES('Test','Test','stats@example.invalid','unused','manager','2026-10-24 03:00:00')");
$db->beginTransaction();foreach(['one','two'] as $op)audit_event($db,1,'save_product',$op,[],[],['transaction_id'=>'shared'],'confirmed','2026-10-24 03:00:00');audit_event($db,1,'session_started','session',['category'=>'users'],[],[],'confirmed','2026-10-24 04:00:00');audit_event($db,1,'save_product','denied',[],[],[],'denied','2026-10-24 04:00:00');audit_event($db,1,'save_product','previous',[],[],[],'confirmed','2026-10-24 02:59:59');$db->commit();
audit_q($db,"INSERT INTO product_reports(submission_key,owner_key,user_id,ean,description,proposed_data,original_data,status,created_at,submitted_at,reviewed_at) VALUES('review','owner',1,'96385074','Test','{}','{}','approved','2026-10-24 03:00:00',0,'2026-10-24 05:00:00')");$stats=moderation_activity($db,$range);stats_ok($stats['registered']===1&&$stats['active_users']===1,'users once');stats_ok($stats['sections']['goods']===1&&$stats['sections']['users']===1,'batch grouping and denied/outside excluded');stats_ok($stats['resolved']===1&&$stats['resolution_hours']===2.0,'resolution time');$empty=moderation_activity($db,moderation_period(['period'=>'custom','from'=>'2026-10-01','to'=>'2026-10-01'],$now));stats_ok($empty['active_users']===0&&$empty['resolution_hours']===null,'empty is not zero duration');echo "OK: periods, Argentina boundaries, grouped transactions, confirmed activity, users, resolution and empty states.\n";
